package com.example.moviejournal.user;

import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

import java.util.Optional;

@Repository
public class UserRepository {
    private final JdbcClient jdbcClient;

    public UserRepository(JdbcClient jdbcClient) {
        this.jdbcClient = jdbcClient;
    }

    /** Inserts the user and returns it with the id generated by the database. */
    public User create(User user) {
        Integer id = jdbcClient.sql("""
                        INSERT INTO users (username, password, role)
                        VALUES (:username, :password, :role)
                        RETURNING id
                        """)
                .param("username", user.username())
                .param("password", user.password())
                .param("role", user.role())
                .query(Integer.class)
                .single();
        return new User(id, user.username(), user.password(), user.role());
    }

    public Optional<User> findByUsername(String username) {
        return jdbcClient.sql("SELECT * FROM users WHERE username = :username")
                .param("username", username)
                .query(User.class)
                .optional();
    }
}
